insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en,warning_fa,warning_en) values
('theme.registry.create','ساخت قالب جدید','قالب جدید از روی یک Theme پایه Clone می‌شود تا Design Tokenها و Component Variantهای معتبر داشته باشد. سپس می‌توان نسخه جدید را مستقل توسعه داد.','Create a new theme','A new theme is cloned from a valid base theme so it starts with supported design tokens and component variants, then can evolve independently.','Theme Key را بعد از استفاده در سایت مشتری تغییر ندهید؛ این شناسه پایدار قالب است.','Do not rename a Theme Key after customers use it; it is the stable theme identifier.'),
('theme.registry.status','وضعیت قالب','Active برای استفاده جدید است، Deprecated برای سازگاری سایت‌های قدیمی باقی می‌ماند و Archived از انتخاب‌های جدید خارج می‌شود.','Theme status','Active is available for new use, Deprecated remains for legacy compatibility, and Archived is removed from new selection.','قالبی که هنوز یک Tenant از آن استفاده می‌کند قابل Archive نیست. ابتدا قالب جایگزین منتشر کنید.','A theme still used by a tenant cannot be archived. Publish a replacement theme first.')
